package fetcher

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	getter "github.com/hashicorp/go-getter"
)

type BundleManifest struct {
	Bundle  string `json:"bundle"`
	Version string `json:"version"`
	SHA256  string `json:"sha256"`
}

type Summary struct {
	Fetched int              `json:"fetched"`
	Bundles []BundleManifest `json:"bundles"`
}

func Run(settings Settings) (Summary, error) {
	if settings.StagingDir == "" {
		return Summary{}, fmt.Errorf("staging_dir is required")
	}
	summary := Summary{Bundles: []BundleManifest{}}
	for _, source := range settings.Sources {
		if source.Name == "" || source.URL == "" {
			return Summary{}, fmt.Errorf("source name and url are required")
		}
		target := filepath.Join(settings.StagingDir, source.Name)
		if err := getter.Get(target, source.URL); err != nil {
			return Summary{}, fmt.Errorf("fetch %s: %w", source.Name, err)
		}
		manifest, err := readManifest(filepath.Join(target, "manifest.json"))
		if err != nil {
			return Summary{}, fmt.Errorf("read manifest for %s: %w", source.Name, err)
		}
		summary.Fetched++
		summary.Bundles = append(summary.Bundles, manifest)
	}
	return summary, nil
}

func readManifest(path string) (BundleManifest, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return BundleManifest{}, err
	}
	var manifest BundleManifest
	if err := json.Unmarshal(data, &manifest); err != nil {
		return BundleManifest{}, err
	}
	return manifest, nil
}
# Meridian Artifact Fetcher

Meridian Artifact Fetcher prepares release bundles for downstream deployment
workers. It reads a small source catalog, fetches each bundle into a staging
directory, and emits a manifest summary that release automation can archive.

## Readiness Check

The refreshed worker image starts with an empty Go module cache. After repairing
module state, run the readiness check from the repository root:

```bash
./scripts/check_fetcher.sh
```

The check validates the dependency safety floor recorded in source, builds the
commands, fetches the configured bundle, and verifies the resulting manifest.
# Artifact Fetcher Operations

The fetcher reads `configs/sources.json` and stages release bundles before the
deployment workers publish them. Source URLs may point at Git repositories or
local release channels produced by the packaging pipeline.

Dependency policy for network-capable fetchers lives in source so module
maintenance follows the same review path as acquisition code.
